```js
/**
 * Fetch one skill resource's raw bytes from the skill bridge.
 * ...
 */
export async function fetchResource({ skillId, path, bridgeBase, fetcher }) {
  const doFetch = fetcher ?? globalThis.fetch;
  const base = String(bridgeBase).replace(/\/+$/, "");
  const url = `${base}/files/download`;
  const res = await doFetch(url, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ skill_id: skillId, path }),
  });

  const raw = Buffer.from(await res.arrayBuffer());

  // files/download returns raw bytes on success. Two cases still come back as
  // a JSON envelope: an error (code !== 0), and an empty resource — the bridge
  // tests `!parsed.data?.content`, and "" is falsy, so a genuinely empty file
  // is returned as the core envelope instead of zero bytes.
  let envelope = null;
  try {
    envelope = JSON.parse(raw.toString("utf-8"));
  } catch {
    // not JSON → raw bytes
  }
  if (envelope && typeof envelope === "object" && typeof envelope.code === "number") {
    if (envelope.code !== 0) {
      throw new Error(envelope.message ?? `bridge returned code ${envelope.code}`);
    }
    const data = envelope.data;
    if (!data || typeof data.content !== "string") {
      throw new Error(envelope.message || "bridge envelope is missing data.content");
    }
    return data.encoding === "base64"
      ? Buffer.from(data.content, "base64")
      : Buffer.from(data.content, "utf-8");
  }
  return raw;
}
```

